package com.clinicbooking.notification.infrastructure.out.sms;
import com.clinicbooking.notification.domain.DeliveryException; import org.junit.jupiter.api.Test; import org.springframework.http.HttpMethod; import org.springframework.http.HttpStatus; import org.springframework.http.MediaType; import org.springframework.test.web.client.MockRestServiceServer; import org.springframework.web.client.RestClient; import static org.junit.jupiter.api.Assertions.*; import static org.springframework.test.web.client.match.MockRestRequestMatchers.*; import static org.springframework.test.web.client.response.MockRestResponseCreators.*;
class TextbeeSmsAdapterTest {
 @Test void sendsAuthenticatedJsonToConfiguredDevice(){/* En producción RestClientsFactory añade x-api-key como header por defecto; el constructor "testable" recibe un RestClient ya armado, así que el test debe hacer lo mismo. */RestClient.Builder b=RestClient.builder().baseUrl("https://api.textbee.dev").defaultHeader("x-api-key","secret");MockRestServiceServer server=MockRestServiceServer.bindTo(b).build();server.expect(requestTo("https://api.textbee.dev/gateway/devices/device-1/send-sms")).andExpect(method(HttpMethod.POST)).andExpect(header("x-api-key","secret")).andExpect(jsonPath("$.recipients[0]").value("+573001234567")).andExpect(jsonPath("$.message").value("Hello")).andRespond(withSuccess("{\"data\":{\"smsBatchId\":\"b1\"}}",MediaType.APPLICATION_JSON));new TextbeeSmsAdapter(b.build(),"secret","device-1").send("+573001234567","Hello");server.verify();}
 @Test void wrapsProviderFailure(){RestClient.Builder b=RestClient.builder().baseUrl("https://api.textbee.dev");MockRestServiceServer server=MockRestServiceServer.bindTo(b).build();server.expect(requestTo("https://api.textbee.dev/gateway/send-sms")).andRespond(withServerError());assertThrows(DeliveryException.class,()->new TextbeeSmsAdapter(b.build(),"key","").send("3001234567","text"));server.verify();}
 @Test void emptyCredentialsUseSafeSimulation(){var adapter=new TextbeeSmsAdapter(RestClient.builder(),"https://api.textbee.dev","","",100,100);assertDoesNotThrow(()->adapter.send("+573001234567","test message"));}
 @Test void internalKeyIsComparedConstantTimeAndOptional(){var disabled=new ClaveServicioValidator("");assertDoesNotThrow(()->disabled.validateIfConfigured(null));var enabled=new ClaveServicioValidator("secret");assertDoesNotThrow(()->enabled.validateIfConfigured("secret"));assertThrows(IllegalArgumentException.class,()->enabled.validateIfConfigured("wrong"));}
}